@Test
void blankMaxSizeStopsStartup() {
    runner.withPropertyValues("device-logs.file-types.app-log.max-size=").run(DeviceLogsPropertiesTest::failedValidation);
}

@Test
void storageWritesToTheEnvironmentBucketWithA60sDeadline() {
    runner.run(context -> {
        DeviceLogsProperties properties = context.getBean(DeviceLogsProperties.class);
        assertThat(properties.aws()).isEqualTo(new DeviceLogsProperties.Aws("us-west-2", null));
        assertThat(properties.storage())
                .isEqualTo(new DeviceLogsProperties.Storage("device-logs-test", Duration.ofSeconds(60)));
    });
}

// A fresh runner, because the shared one's bucket would win over the profile's.
@Test
void localTestPointsAtLocalStack() {
    new ApplicationContextRunner().withInitializer(new ConfigDataApplicationContextInitializer())
            .withUserConfiguration(Config.class).withPropertyValues("spring.profiles.active=local-test")
            .run(context -> {
        DeviceLogsProperties properties = context.getBean(DeviceLogsProperties.class);
        assertThat(properties.aws().endpointOverride()).isEqualTo(URI.create("http://localhost:4566"));
        assertThat(properties.storage().bucket()).isEqualTo("device-logs-local");
    });
}

@ParameterizedTest
@ValueSource(strings = { "device-logs.aws.region=", "device-logs.storage.bucket= ",
        "device-logs.storage.write-timeout=", "device-logs.storage.write-timeout=0s" })
void missingStorageSettingStopsStartup(String override) {
    runner.withPropertyValues(override).run(DeviceLogsPropertiesTest::failedValidation);
}

@Test
void anEnvironmentWithoutABucketStopsStartup() {
    new ApplicationContextRunner().withInitializer(new ConfigDataApplicationContextInitializer())
            .withUserConfiguration(Config.class).withPropertyValues("device-logs.aws.region=us-west-2")
            .run(DeviceLogsPropertiesTest::failedValidation);
}

// Without application.yml, so the only file types are the ones given here.
